def isWildcardMatch(s, p):
    i = j = 0
    m, n = len(s), len(p)
    star = -1          # index of the latest '*' in p
    mark = 0           # index in s where that star started absorbing
    while i < m:
        if j < n and (p[j] == '?' or p[j] == s[i]):
            i += 1
            j += 1
        elif j < n and p[j] == '*':
            star = j
            mark = i
            j += 1
        elif star != -1:
            j = star + 1
            mark += 1
            i = mark
        else:
            return False
    while j < n and p[j] == '*':
        j += 1
    return j == n
